// Fourth review of the workbook view: a dialog of rules (data validation, conditional format,
// the list of rules) is modal and the user's to confirm - saving, undo and changes from outside
// close it when nothing was changed in it and leave it alone otherwise; the bridge says "done"
// only for what was done; a long list of rules is shown in runs; a copy of cells outlives what
// does not change the names of the sheets. Every workbook is generated by code.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;
const CELLS = `<sheetData><row r="1">${num('A1', 1)}${num('B1', 10)}</row><row r="2">${num('A2', 5)}${num('B2', 20)}</row><row r="3">${num('A3', 9)}</row></sheetData>`;

const workbook = () =>
  buildXlsx({
    sheets: [
      { name: 'Data', xml: worksheetXml(CELLS) },
      { name: 'Calc', xml: worksheetXml(`<sheetData><row r="1"><c r="A1"><f>Data!A1+1</f><v>2</v></c></row></sheetData>`) },
      { name: 'Notes', xml: worksheetXml('<sheetData/>') },
    ],
  });

async function mountPage(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/mount.html');
  await page.evaluate(
    async ([input, options]) => {
      const w = window as any;
      w.__saved = [];
      w.__notices = [];
      w.__mounted = await w.BymOffice.mount(document.getElementById('editor'), {
        file: new Uint8Array(input as number[]),
        locale: 'en-US',
        onSave: (bytes: Uint8Array) => w.__saved.push(Array.from(bytes)),
        onNotice: (notice: any) => w.__notices.push({ message: notice.message, kind: notice.kind }),
        ...(options as object),
      });
    },
    [Array.from(bytes), options] as [number[], Record<string, unknown>],
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

const mounted = <T>(page: Page, run: string): Promise<T> => page.evaluate(`(async () => { const mounted = window.__mounted; const view = mounted.view; const api = window.BymOffice; return ${run}; })()`) as Promise<T>;
const dialog = (page: Page, name = 'conditional') => page.locator(`[data-bym-dialog="${name}"]`);
const field = (page: Page, name: string, of = 'conditional') => dialog(page, of).locator(`[data-bym-field="${name}"]`);
const action = (page: Page, name: string, of = 'conditional') => dialog(page, of).locator(`[data-bym-action="${name}"]`);
const alert = (page: Page, name = 'conditional') => dialog(page, name).locator('[role="alert"]');
const notices = (page: Page) => page.evaluate(() => ((window as any).__notices as { message: string }[]).map((notice) => notice.message));
const ruleCount = (page: Page) => mounted<number>(page, 'view.conditionalRules().length');
const validationCount = (page: Page) => mounted<number>(page, '(view.workbook.sheets[view.activeSheet].dataValidations || []).length');
const select = (page: Page, ref: string) => mounted(page, `(view.select(api.parseRange(${JSON.stringify(ref)})), view.focus(), true)`);
const OPEN = 'Confirm or close the open rule dialog first';

const NEW_RULES = ['cellIs', 'containsText', 'notContainsText', 'beginsWith', 'endsWith', 'duplicateValues', 'uniqueValues', 'top10', 'aboveAverage', 'containsBlanks', 'notContainsBlanks', 'containsErrors', 'notContainsErrors', 'expression', 'colorScale', 'dataBar'];

test.describe('a dialog of rules that is open when the workbook is taken', () => {
  test('a dialog of a new rule in which nothing was changed is closed by saving, and no rule is made, whatever its kind', async ({ page }) => {
    const bytes = await workbook();
    await mountPage(page, bytes);
    for (const kind of NEW_RULES) {
      await select(page, 'A1:A3');
      expect(await mounted(page, `view.openConditionalDialog(${JSON.stringify(kind)})`), kind).toBe(true);
      await expect(dialog(page)).toBeVisible();
      const saved = await mounted<number[]>(page, 'Array.from(await mounted.save())');
      await expect(dialog(page)).toHaveCount(0);
      expect(await ruleCount(page), kind).toBe(0);
      expect(saved, kind).toEqual(Array.from(bytes));
    }
    expect(await mounted(page, 'view.history.canUndo')).toBe(false);
    // The dialog of data validation and the list of rules: the same.
    expect(await mounted(page, 'view.openValidationDialog()')).toBe(true);
    expect(await mounted(page, 'view.commitPending()')).toBe(true);
    await expect(dialog(page, 'validation')).toHaveCount(0);
    expect(await validationCount(page)).toBe(0);
    expect(await mounted(page, 'view.openConditionalDialog("manage")')).toBe(true);
    expect(await mounted(page, 'view.commitPending()')).toBe(true);
    await expect(dialog(page, 'conditional-rules')).toHaveCount(0);
    expect(await notices(page)).toEqual([]);
  });

  test('a dialog with changes stays open: nothing of it is applied, nothing is saved, and that is said', async ({ page }) => {
    await mountPage(page, await workbook());
    await select(page, 'A1:A3');
    expect(await mounted(page, 'view.openConditionalDialog("greaterThan")')).toBe(true);
    await field(page, 'value1').fill('4');
    expect(await mounted(page, 'view.commitPending()')).toBe(false);
    await expect(dialog(page)).toBeVisible();
    await expect(field(page, 'value1')).toHaveValue('4');
    await expect(alert(page)).toHaveText(OPEN);
    expect(await ruleCount(page)).toBe(0);
    expect(await notices(page)).toEqual([OPEN]);
    // mount().save() refuses, and onSave is not called.
    const refused = await mounted<string>(page, 'mounted.save().then(() => "saved", (error) => String(error.message))');
    expect(refused).toMatch(/dialog of rules is open with changes/);
    expect(await page.evaluate(() => (window as any).__saved.length)).toBe(0);
    expect(await ruleCount(page)).toBe(0);
    await expect(dialog(page)).toBeVisible();
    // The user confirms: the rule is made, and the workbook can be saved with it.
    await action(page, 'ok').click();
    await expect(dialog(page)).toHaveCount(0);
    expect(await ruleCount(page)).toBe(1);
    const saved = await mounted<number>(page, '(await mounted.save()).length');
    expect(saved).toBeGreaterThan(0);
    // A field put back to what it was is no change.
    expect(await mounted(page, 'view.openConditionalDialog("greaterThan")')).toBe(true);
    await field(page, 'value1').fill('7');
    await field(page, 'value1').fill('');
    expect(await mounted(page, 'view.commitPending()')).toBe(true);
    await expect(dialog(page)).toHaveCount(0);
    expect(await ruleCount(page)).toBe(1);
  });

  test('the dialog of data validation with changes is not applied by saving either; Cancel gives them up', async ({ page }) => {
    await mountPage(page, await workbook());
    await select(page, 'B1:B2');
    expect(await mounted(page, 'view.openValidationDialog()')).toBe(true);
    await field(page, 'type', 'validation').selectOption('whole');
    await field(page, 'operator', 'validation').selectOption('equal');
    await field(page, 'value1', 'validation').fill('4');
    expect(await mounted(page, 'view.commitPending()')).toBe(false);
    await expect(alert(page, 'validation')).toHaveText(OPEN);
    expect(await validationCount(page)).toBe(0);
    await action(page, 'cancel', 'validation').click();
    await expect(dialog(page, 'validation')).toHaveCount(0);
    expect(await validationCount(page)).toBe(0);
    expect(await mounted(page, 'view.commitPending()')).toBe(true);
    expect(await mounted(page, 'view.history.canUndo')).toBe(false);
  });

  test('cells typed for a rule of the list and not applied yet keep the list open', async ({ page }) => {
    await mountPage(page, await workbook());
    await select(page, 'A1:A3');
    await mounted(page, '(view.addConditionalRule(api.parseRange("A1:A3"), { type: "duplicateValues" }), true)');
    expect(await mounted(page, 'view.openConditionalDialog("manage")')).toBe(true);
    const ranges = dialog(page, 'conditional-rules').locator('[data-bym-rule="0"] [data-bym-field="ranges"]');
    await ranges.evaluate((el) => ((el as HTMLInputElement).value = 'A1:A2'));
    expect(await mounted(page, 'view.commitPending()')).toBe(false);
    await expect(dialog(page, 'conditional-rules')).toBeVisible();
    await expect(alert(page, 'conditional-rules')).toHaveText(OPEN);
    expect(await mounted(page, 'api.rangeName(view.conditionalRules()[0].ranges[0])')).toBe('A1:A3');
    // Applied by the user (Enter in the field), the list has nothing waiting and is closed for a save.
    await ranges.focus();
    await page.keyboard.press('Enter');
    expect(await mounted(page, 'api.rangeName(view.conditionalRules()[0].ranges[0])')).toBe('A1:A2');
    expect(await mounted(page, 'view.commitPending()')).toBe(true);
    await expect(dialog(page, 'conditional-rules')).toHaveCount(0);
  });
});

test.describe('undo, redo and changes from outside under a dialog of rules', () => {
  test('undo and redo do nothing while a dialog of rules is open, changed or not', async ({ page }) => {
    await mountPage(page, await workbook());
    await mounted(page, '(view.setCellInput(0, 2, "typed"), true)');
    expect(await mounted(page, 'view.history.canUndo')).toBe(true);
    await select(page, 'A1:A3');
    expect(await mounted(page, 'view.openConditionalDialog("greaterThan")')).toBe(true);
    expect(await mounted(page, 'view.undo()')).toBe(false);
    await expect(dialog(page)).toBeVisible();
    expect(await mounted(page, 'api.getCell(view.workbook.sheets[0], 0, 2).value')).toBe('typed');
    await field(page, 'value1').fill('4');
    expect(await mounted(page, 'view.undo()')).toBe(false);
    expect(await mounted(page, 'view.redo()')).toBe(false);
    await expect(dialog(page)).toBeVisible();
    await expect(field(page, 'value1')).toHaveValue('4');
    expect(await ruleCount(page)).toBe(0);
    expect(await mounted(page, 'api.getCell(view.workbook.sheets[0], 0, 2).value')).toBe('typed');
    await page.keyboard.press('Escape');
    await expect(dialog(page)).toHaveCount(0);
    expect(await mounted(page, 'view.undo()')).toBe(true);
    expect(await mounted(page, 'api.getCell(view.workbook.sheets[0], 0, 2)')).toBeFalsy();
  });

  test('a change from outside closes a dialog nothing was changed in, and is made', async ({ page }) => {
    await mountPage(page, await workbook());
    const changesMade: [string, string][] = [
      ['view.insertRows(0, 1)', 'view.workbook.sheets[0].rows.has(3)'],
      ['view.setCellInput(5, 0, "x")', 'api.getCell(view.workbook.sheets[0], 5, 0).value === "x"'],
      ['view.sort(true)', 'true'],
      ['view.paste("pasted")', 'true'],
      ['view.addConditionalRule(api.parseRange("B1:B2"), { type: "uniqueValues" })', 'view.conditionalRules().length === 1'],
      ['view.setValidation(api.parseRange("C1"), { type: "list", formula1: \'"a,b"\' })', '(view.workbook.sheets[0].dataValidations || []).length === 1'],
    ];
    for (const [run, check] of changesMade) {
      await select(page, 'A1:A3');
      expect(await mounted(page, 'view.openConditionalDialog("greaterThan")'), run).toBe(true);
      await mounted(page, `(${run}, true)`);
      await expect(dialog(page), run).toHaveCount(0);
      expect(await mounted(page, check), run).toBe(true);
    }
    expect(await notices(page)).toEqual([]);
  });

  test('a change from outside is refused under a dialog with changes: the dialog and the workbook stay as they are', async ({ page }) => {
    await mountPage(page, await workbook());
    await select(page, 'A1:A3');
    expect(await mounted(page, 'view.openConditionalDialog("greaterThan")')).toBe(true);
    await field(page, 'value1').fill('4');
    const before = await mounted<string>(page, 'JSON.stringify([view.workbook.sheets.map((sheet) => sheet.name), Array.from(view.workbook.sheets[0].rows.keys()), view.conditionalRules().length, view.history.canUndo])');
    for (const run of [
      'view.insertRows(0, 1)',
      'view.deleteRows(0, 1)',
      'view.setCellInput(5, 0, "x")',
      'view.sort(true)',
      'view.paste("pasted")',
      'view.clearSelection()',
      'view.addConditionalRule(api.parseRange("B1:B2"), { type: "uniqueValues" })',
      'view.setValidation(api.parseRange("C1"), { type: "list", formula1: \'"a,b"\' })',
      'view.renameSheet(1, "Other")',
      'view.deleteSheet(2)',
      'view.moveSheet(0, 2)',
      'view.setTabColor(0, "#FF0000")',
      'view.insertSheet()',
      'view.copySheet(0)',
    ]) {
      await mounted(page, `(${run}, true)`);
      await expect(dialog(page), run).toBeVisible();
      await expect(field(page, 'value1'), run).toHaveValue('4');
      const now = await mounted<string>(page, 'JSON.stringify([view.workbook.sheets.map((sheet) => sheet.name), Array.from(view.workbook.sheets[0].rows.keys()), view.conditionalRules().length, view.history.canUndo])');
      expect(now, run).toBe(before);
    }
    expect((await notices(page)).every((message) => message === OPEN)).toBe(true);
    // OK makes the rule the dialog was opened for, on the cells it was opened for.
    await action(page, 'ok').click();
    expect(await mounted(page, 'view.conditionalRules().map((info) => api.rangeName(info.ranges[0]) + " " + info.rule.formulas[0]).join()')).toBe('A1:A3 4');
  });

  test('a view made read-only closes the dialog and what was changed in it is given up', async ({ page }) => {
    await mountPage(page, await workbook());
    await select(page, 'A1:A3');
    expect(await mounted(page, 'view.openConditionalDialog("greaterThan")')).toBe(true);
    await field(page, 'value1').fill('4');
    await mounted(page, '(view.setReadOnly(true), true)');
    await expect(dialog(page)).toHaveCount(0);
    expect(await ruleCount(page)).toBe(0);
  });

  test('a tab that is being dragged is let go when a dialog of rules opens', async ({ page, hasTouch }) => {
    test.skip(hasTouch, 'a drag by mouse');
    await mountPage(page, await workbook());
    const tab = (name: string) => page.locator('.bym-tabs button.bym-tab', { hasText: name });
    const from = (await tab('Data').boundingBox())!;
    const to = (await tab('Notes').boundingBox())!;
    await page.mouse.move(from.x + from.width / 2, from.y + from.height / 2);
    await page.mouse.down();
    await page.mouse.move(to.x + to.width - 4, to.y + to.height / 2, { steps: 4 });
    await expect(page.locator('.bym-tabs .bym-tab-drop')).toHaveCount(1);
    for (const [open, name] of [
      ['view.openValidationDialog()', 'validation'],
      ['view.openConditionalDialog("greaterThan")', 'conditional'],
    ]) {
      expect(await mounted(page, open)).toBe(true);
      await expect(page.locator('.bym-tabs .bym-tab-drop')).toHaveCount(0);
      await expect(dialog(page, name)).toBeVisible();
      await page.keyboard.press('Escape');
      await expect(dialog(page, name)).toHaveCount(0);
    }
    await page.mouse.up();
    await expect(page.locator('.bym-tabs button.bym-tab')).toHaveText(['Data', 'Calc', 'Notes']);
    expect(await mounted(page, 'view.history.canUndo')).toBe(false);
  });
});

test.describe('calls from outside that would put something else in the place of a dialog of rules', () => {
  /** A list in A1 and a filter over A1:B3, so that every call has something to open. */
  const prepared = async (page: Page) => {
    await mountPage(page, await workbook());
    await mounted(page, '(view.setValidation(api.parseRange("A1"), { type: "list", formula1: \'"1,2,3"\' }), view.select(api.parseRange("A1:B3")), view.toggleFilter(), true)');
    await select(page, 'A1');
  };
  /** What the view shows beside the dialog: nothing of it may appear under a dialog with changes. */
  const beside = (page: Page) =>
    page.evaluate(() => {
      const view = (window as any).__mounted.view;
      const count = (selector: string) => document.querySelectorAll(selector).length;
      return { editing: view.isEditing, note: count('.bym-note-input'), name: count('.bym-tab-input'), list: count('.bym-dropdown'), filter: count('.bym-filter'), validation: count('[data-bym-dialog="validation"]'), rules: count('[data-bym-dialog="conditional-rules"]'), label: count('[aria-label="Spreadsheet"]') > 0, sheet: view.activeSheet };
    });
  const NOTHING = { editing: false, note: 0, name: 0, list: 0, filter: 0, validation: 0, rules: 0, label: true, sheet: 0 };
  const CALLS: [run: string, answer: unknown][] = [
    ['view.startEditing("typed")', undefined],
    ['view.setEditText("typed")', undefined],
    ['view.editComment(0, 0)', false],
    ['view.editComment()', false],
    ['view.startRename(1)', false],
    ['view.openValidationList()', false],
    ['view.openFilterMenu(0)', false],
    ['view.openValidationDialog()', false],
    ['view.openConditionalDialog("manage")', false],
    ['view.openConditionalDialog("lessThan")', false],
  ];

  test('under a dialog with changes each of them is refused: the dialog stays as it is, and that is said', async ({ page }) => {
    await prepared(page);
    expect(await mounted(page, 'view.openConditionalDialog("greaterThan")')).toBe(true);
    await field(page, 'value1').fill('4');
    const steps = await mounted<boolean>(page, 'view.history.canUndo');
    for (const [run, answer] of CALLS) {
      await page.evaluate(() => ((window as any).__notices.length = 0));
      expect(await mounted(page, `(() => { const answer = ${run}; return answer === undefined ? null : answer; })()`), run).toBe(answer === undefined ? null : answer);
      await expect(dialog(page), run).toBeVisible();
      await expect(field(page, 'value1'), run).toHaveValue('4');
      await expect(alert(page), run).toHaveText(OPEN);
      expect(await notices(page), run).toEqual([OPEN]);
      expect(await beside(page), run).toEqual(NOTHING);
    }
    // Another language is refused the same way, and the caller hears of it: the view keeps the one it has.
    await page.evaluate(() => ((window as any).__notices.length = 0));
    expect(await mounted(page, '(() => { try { view.setLocale("tr"); return "changed"; } catch (error) { return error instanceof RangeError ? error.message : String(error); } })()')).toBe(OPEN);
    expect(await notices(page)).toEqual([OPEN]);
    expect(await beside(page)).toEqual(NOTHING);
    await expect(dialog(page)).toBeVisible();
    await expect(field(page, 'value1')).toHaveValue('4');
    expect(await mounted(page, 'view.history.canUndo')).toBe(steps);
    // OK makes the rule the dialog was opened for.
    await action(page, 'ok').click();
    expect(await mounted(page, 'view.conditionalRules().map((info) => api.rangeName(info.ranges[0]) + " " + info.rule.formulas[0]).join()')).toBe('A1 4');
  });

  test('under a dialog nothing was changed in, each of them closes the dialog and is done', async ({ page }) => {
    await prepared(page);
    const done: [run: string, shown: Partial<typeof NOTHING>, undo: string][] = [
      ['view.startEditing("typed")', { editing: true }, 'view.cancelEditing()'],
      ['view.setEditText("typed")', { editing: true }, 'view.cancelEditing()'],
      ['view.editComment(0, 0)', { note: 1 }, 'view.commitPending()'],
      ['view.startRename(1)', { name: 1, sheet: 1 }, '(view.commitPending(), view.setActiveSheet(0))'],
      ['view.openValidationList()', { list: 1 }, '(view.setActiveSheet(1), view.setActiveSheet(0))'],
      ['view.openFilterMenu(0)', { filter: 1 }, '(view.setActiveSheet(1), view.setActiveSheet(0))'],
      ['view.openValidationDialog()', { validation: 1 }, 'view.commitPending()'],
      ['view.openConditionalDialog("manage")', { rules: 1 }, 'view.commitPending()'],
      ['view.setLocale("tr")', { label: false }, 'view.setLocale("en-US")'],
    ];
    for (const [run, shown, undo] of done) {
      await select(page, 'A1');
      expect(await mounted(page, 'view.openConditionalDialog("greaterThan")'), run).toBe(true);
      await expect(dialog(page), run).toBeVisible();
      await mounted(page, `(${run}, true)`);
      await expect(dialog(page), run).toHaveCount(0);
      expect(await beside(page), run).toEqual({ ...NOTHING, ...shown });
      await mounted(page, `(${undo}, true)`);
      await page.keyboard.press('Escape');
      await expect.poll(() => beside(page), { message: `${run}: put away again` }).toEqual(NOTHING);
    }
    expect(await notices(page)).toEqual([]);
    expect(await ruleCount(page)).toBe(0);
  });

  test('a sheet shown from outside and a view made read-only close a dialog with changes, and what was changed in it is given up', async ({ page }) => {
    await prepared(page);
    expect(await mounted(page, 'view.openConditionalDialog("greaterThan")')).toBe(true);
    await field(page, 'value1').fill('4');
    await mounted(page, '(view.setActiveSheet(2), true)');
    await expect(dialog(page)).toHaveCount(0);
    expect(await mounted(page, 'view.activeSheet')).toBe(2);
    await mounted(page, '(view.setActiveSheet(0), true)');
    expect(await ruleCount(page)).toBe(0);
    await select(page, 'A1');
    expect(await mounted(page, 'view.openValidationDialog()')).toBe(true);
    await field(page, 'type', 'validation').selectOption('whole');
    await mounted(page, '(view.setReadOnly(true), true)');
    await expect(dialog(page, 'validation')).toHaveCount(0);
    expect(await mounted(page, 'view.workbook.sheets[0].dataValidations.length')).toBe(1);
    expect(await mounted(page, 'view.history.canUndo')).toBe(true);
  });

  test('a dialog that shows another sheet for a formula to point at: a note is not opened under one with changes, and is opened on its own sheet otherwise', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, 'the tab is pressed with the mouse');
    await mountPage(page, await workbook());
    const away = async () => {
      await select(page, 'A1:A3');
      expect(await mounted(page, 'view.openConditionalDialog("expression")')).toBe(true);
      await field(page, 'value1').click();
      const tab = (await page.locator('.bym-tabs button.bym-tab', { hasText: 'Calc' }).boundingBox())!;
      await page.mouse.click(tab.x + tab.width / 2, tab.y + tab.height / 2);
      await expect.poll(() => mounted(page, 'view.activeSheet')).toBe(1);
      await expect(dialog(page)).toBeVisible();
    };
    // Nothing changed in it: the dialog is closed, its own sheet is shown again, and the note is one of that sheet.
    await away();
    expect(await mounted(page, 'view.editComment(1, 0)')).toBe(true);
    await expect(dialog(page)).toHaveCount(0);
    expect(await mounted(page, 'view.activeSheet')).toBe(0);
    await expect(page.locator('.bym-note-input')).toHaveCount(1);
    await page.locator('.bym-note-input').fill('on Data');
    expect(await mounted(page, 'view.commitPending()')).toBe(true);
    expect(await mounted(page, 'view.workbook.sheets.map((sheet) => (sheet.comments || []).length).join()')).toBe('1,0,0');
    // With something typed into it: the dialog stays, with the sheet it shows, and no note is opened anywhere.
    await away();
    await field(page, 'value1').fill('=A1>2');
    expect(await mounted(page, 'view.editComment(1, 0)')).toBe(false);
    await expect(dialog(page)).toBeVisible();
    await expect(field(page, 'value1')).toHaveValue('=A1>2');
    await expect(alert(page)).toHaveText(OPEN);
    expect(await mounted(page, 'view.activeSheet')).toBe(1);
    await expect(page.locator('.bym-note-input')).toHaveCount(0);
    expect((await notices(page)).slice(-1)).toEqual([OPEN]);
  });
});

test.describe('the list of rules of a sheet with more than it shows at once', () => {
  test('the rules after the first 200 are reached, changed and deleted from the list', async ({ page }) => {
    let rulesXml = '';
    for (let i = 1; i <= 450; i++) rulesXml += `<cfRule type="cellIs" priority="${i}" operator="equal"><formula>${i}</formula></cfRule>`;
    await mountPage(page, await buildXlsx({ sheets: [{ name: 'Data', xml: worksheetXml(`${CELLS}<conditionalFormatting sqref="A1:A3">${rulesXml}</conditionalFormatting>`) }] }));
    expect(await mounted(page, 'view.openConditionalDialog("manage")')).toBe(true);
    const manager = dialog(page, 'conditional-rules');
    await field(page, 'scope', 'conditional-rules').selectOption('sheet');
    const rows = manager.locator('[data-bym-rule]');
    const more = manager.locator('[data-bym-field="more"]');
    const first = manager.locator('[data-bym-rule="0"] .bym-dialog-rule-text');
    await expect(rows).toHaveCount(200);
    await expect(more).toHaveText('Rules 1 to 200 of 450');
    await expect(action(page, 'previous-page', 'conditional-rules')).toBeDisabled();
    await expect(action(page, 'next-page', 'conditional-rules')).toHaveText('Next 200');
    await action(page, 'next-page', 'conditional-rules').click();
    await expect(more).toHaveText('Rules 201 to 400 of 450');
    await expect(first).toHaveText('Cell value equal to 201');
    await expect(action(page, 'next-page', 'conditional-rules')).toHaveText('Next 50');
    await action(page, 'next-page', 'conditional-rules').click();
    await expect(rows).toHaveCount(50);
    await expect(more).toHaveText('Rules 401 to 450 of 450');
    await expect(action(page, 'next-page', 'conditional-rules')).toBeDisabled();
    // The cells of rule 401, and rule 402 deleted.
    const ranges = manager.locator('[data-bym-rule="0"] [data-bym-field="ranges"]');
    await ranges.fill('B1:B2');
    await ranges.press('Enter');
    expect(await mounted(page, 'api.rangeName(view.conditionalRules()[400].ranges[0])')).toBe('B1:B2');
    await expect(more).toHaveText('Rules 401 to 450 of 450');
    await manager.locator('[data-bym-rule="1"] [data-bym-action="delete"]').click();
    await expect(more).toHaveText('Rules 401 to 449 of 449');
    expect(await mounted(page, 'view.conditionalRules().length')).toBe(449);
    expect(await mounted(page, 'view.conditionalRules()[401].rule.formulas[0]')).toBe('403');
    // The first rule of a run moves above the last of the run before it.
    await action(page, 'previous-page', 'conditional-rules').click();
    await expect(first).toHaveText('Cell value equal to 201');
    await manager.locator('[data-bym-rule="0"] [data-bym-action="up"]').click();
    expect(await mounted(page, 'view.conditionalRules().slice(199, 201).map((info) => info.rule.formulas[0]).join()')).toBe('201,200');
    await expect(first).toHaveText('Cell value equal to 200');
    // Its own dialog, and back to the same run of the list.
    await manager.locator('[data-bym-rule="3"] [data-bym-action="edit"]').click();
    await expect(field(page, 'value1')).toHaveValue('204');
    await page.keyboard.press('Escape');
    await expect(manager).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(manager).toHaveCount(0);
  });

  test('when the rules of the last run are deleted the list shows the run before it', async ({ page }) => {
    let rulesXml = '';
    for (let i = 1; i <= 201; i++) rulesXml += `<cfRule type="cellIs" priority="${i}" operator="equal"><formula>${i}</formula></cfRule>`;
    await mountPage(page, await buildXlsx({ sheets: [{ name: 'Data', xml: worksheetXml(`${CELLS}<conditionalFormatting sqref="A1:A3">${rulesXml}</conditionalFormatting>`) }] }));
    expect(await mounted(page, 'view.openConditionalDialog("manage")')).toBe(true);
    const manager = dialog(page, 'conditional-rules');
    await field(page, 'scope', 'conditional-rules').selectOption('sheet');
    await action(page, 'next-page', 'conditional-rules').click();
    await expect(manager.locator('[data-bym-rule]')).toHaveCount(1);
    await manager.locator('[data-bym-rule="0"] [data-bym-action="delete"]').click();
    await expect(manager.locator('[data-bym-rule]')).toHaveCount(200);
    await expect(manager.locator('[data-bym-field="more"]')).toHaveCount(0);
    await expect(manager.locator('[data-bym-rule="0"] .bym-dialog-rule-text')).toHaveText('Cell value equal to 1');
  });
});

test.describe('a copy of cells and the sheets', () => {
  /** Copies Calc!A1 (a formula that names Data), does something to the sheets, pastes into Calc!A3 and says what A3 holds. */
  async function copyThenPaste(page: Page, between: string): Promise<{ formula: string | null; value: unknown }> {
    await mountPage(page, await workbook());
    await mounted(page, '(view.setActiveSheet(1), true)');
    await select(page, 'A1');
    await mounted(page, '(window.__copied = view.copy(), true)');
    await mounted(page, `(${between}, true)`);
    return mounted(
      page,
      `(() => {
        const at = view.workbook.sheets.findIndex((sheet) => sheet.name === 'Calc' || sheet.name === 'Sums');
        view.setActiveSheet(at);
        view.select(api.parseRange('A3'));
        view.paste(window.__copied.text, window.__copied.html);
        const cell = api.getCell(view.workbook.sheets[at], 2, 0);
        return { formula: cell && cell.formula ? cell.formula.text : null, value: cell ? cell.value : null };
      })()`,
    );
  }

  test('a tab coloured, a sheet moved, hidden, added or copied leaves the copy what it was: its formula is pasted', async ({ page }) => {
    for (const between of ['view.setTabColor(0, "#00FF00")', 'view.moveSheet(2, 0)', 'view.setSheetState(2, "hidden")', 'view.insertSheet()', 'view.copySheet(0)']) {
      const pasted = await copyThenPaste(page, between);
      expect(pasted.formula, between).toBe('Data!A3+1');
    }
  });

  test('a sheet renamed or deleted makes the copy text: what it showed is pasted, not a formula of names that are gone', async ({ page }) => {
    for (const between of ['view.renameSheet(0, "Source")', 'view.deleteSheet(2)', 'view.renameSheet(1, "Sums")']) {
      const pasted = await copyThenPaste(page, between);
      expect(pasted.formula, between).toBeNull();
      expect(pasted.value, between).toBe(2);
    }
  });
});

test.describe('the bridge and what the view did not do', () => {
  test('a command on sheets under a dialog with changes is answered with sheet-refused, and done once the dialog is gone', async ({ page }) => {
    await page.addInitScript(() => {
      (window as any).__messages = [];
      (window as any).BymOfficeHost = { postMessage: (json: unknown) => (window as any).__messages.push(json) };
    });
    await page.goto('/dist/bymoffice.webview.html');
    const send = (message: unknown) => page.evaluate((json) => (window as any).BymOfficeBridge.receive(json), JSON.stringify(message));
    const messages = (type: string) => page.evaluate((type) => ((window as any).__messages as string[]).map((entry) => JSON.parse(entry)).filter((message) => message.type === type), type);
    await send({ type: 'load', id: 'l', data: Buffer.from(await workbook()).toString('base64'), locale: 'en-US' });
    await expect.poll(async () => (await messages('loaded')).length).toBe(1);
    // The dialog of data validation, opened by the user from the toolbar of the page, with a field changed.
    await page.locator('.bym-input').focus();
    await page.locator('[data-command="validation"]').click();
    await expect(dialog(page, 'validation')).toBeVisible();
    await field(page, 'type', 'validation').selectOption('whole');
    const commands = [
      { type: 'renameSheet', index: 0, name: 'Renamed' },
      { type: 'deleteSheet', index: 2 },
      { type: 'moveSheet', from: 0, to: 2 },
      { type: 'setSheetState', index: 2, state: 'hidden' },
      { type: 'setTabColor', index: 0, color: '#FF0000' },
      { type: 'insertSheet' },
      { type: 'copySheet', index: 0 },
    ];
    for (let i = 0; i < commands.length; i++) {
      await send({ ...commands[i], id: `c${i}` });
      await expect.poll(async () => (await messages('error')).length, { message: commands[i].type }).toBe(i + 1);
      const error = (await messages('error'))[i];
      expect([error.id, error.code], commands[i].type).toEqual([`c${i}`, 'sheet-refused']);
      expect(error.message).toMatch(/dialog of rules is open with changes/);
    }
    expect(await messages('done')).toEqual([]);
    expect(await messages('sheets')).toEqual([]);
    await expect(dialog(page, 'validation')).toBeVisible();
    // A save is refused the same way, and an undo does nothing.
    await send({ type: 'save', id: 's' });
    await expect.poll(async () => (await messages('error')).length).toBe(commands.length + 1);
    expect((await messages('error'))[commands.length]).toMatchObject({ id: 's', code: 'save-failed' });
    expect(await messages('saved')).toEqual([]);
    // Given up by the user, the same command is done and said to be.
    await action(page, 'cancel', 'validation').click();
    await expect(dialog(page, 'validation')).toHaveCount(0);
    await send({ ...commands[0], id: 'again' });
    await expect.poll(async () => (await messages('done')).length).toBe(1);
    expect((await messages('done'))[0]).toEqual({ type: 'done', id: 'again', command: 'renameSheet' });
    expect((await messages('sheets'))[0].sheets[0].name).toBe('Renamed');
    // Under a dialog nothing was changed in, the command closes the dialog and is done.
    await page.locator('.bym-input').focus();
    await page.locator('[data-command="validation"]').click();
    await expect(dialog(page, 'validation')).toBeVisible();
    await send({ type: 'setTabColor', id: 'tc', index: 0, color: '#00FF00' });
    await expect.poll(async () => (await messages('done')).length).toBe(2);
    await expect(dialog(page, 'validation')).toHaveCount(0);
  });
});

test.describe('the bridge and a language asked for under a dialog of rules', () => {
  test('setLocale under a dialog with changes is answered with locale-refused and nothing changes its language; under one without, it is done', async ({ page }) => {
    await page.addInitScript(() => {
      (window as any).__messages = [];
      (window as any).BymOfficeHost = { postMessage: (json: unknown) => (window as any).__messages.push(json) };
    });
    await page.goto('/dist/bymoffice.webview.html');
    const send = (message: unknown) => page.evaluate((json) => (window as any).BymOfficeBridge.receive(json), JSON.stringify(message));
    const messages = (type: string) => page.evaluate((type) => ((window as any).__messages as string[]).map((entry) => JSON.parse(entry)).filter((message) => message.type === type), type);
    await send({ type: 'load', id: 'l', data: Buffer.from(await workbook()).toString('base64'), locale: 'en-US' });
    await expect.poll(async () => (await messages('loaded')).length).toBe(1);
    const button = page.locator('[data-command="validation"]');
    const label = await button.getAttribute('aria-label');
    await page.locator('.bym-input').focus();
    await button.click();
    await expect(dialog(page, 'validation')).toBeVisible();
    await field(page, 'type', 'validation').selectOption('whole');
    await send({ type: 'setLocale', id: 'tr', locale: 'tr' });
    await expect.poll(async () => (await messages('error')).length).toBe(1);
    expect((await messages('error'))[0]).toEqual({ type: 'error', id: 'tr', code: 'locale-refused', message: OPEN });
    expect(await messages('done')).toEqual([]);
    await expect(dialog(page, 'validation')).toBeVisible();
    await expect(alert(page, 'validation')).toHaveText(OPEN);
    // Neither the view nor the bars around it speak another language.
    await expect(page.locator('[aria-label="Spreadsheet"]')).toHaveCount(1);
    expect(await button.getAttribute('aria-label')).toBe(label);
    // Given up by the user, the same command is done.
    await action(page, 'cancel', 'validation').click();
    await expect(dialog(page, 'validation')).toHaveCount(0);
    await send({ type: 'setLocale', id: 'again', locale: 'tr' });
    await expect.poll(async () => (await messages('done')).length).toBe(1);
    expect((await messages('done'))[0]).toEqual({ type: 'done', id: 'again', command: 'setLocale' });
    await expect(page.locator('[aria-label="Hesap tablosu"]')).toHaveCount(1);
    expect(await button.getAttribute('aria-label')).not.toBe(label);
    // Under a dialog nothing was changed in, the command closes the dialog and is done.
    await page.locator('.bym-input').focus();
    await button.click();
    await expect(dialog(page, 'validation')).toBeVisible();
    await send({ type: 'setLocale', id: 'en', locale: 'en-US' });
    await expect.poll(async () => (await messages('done')).length).toBe(2);
    await expect(dialog(page, 'validation')).toHaveCount(0);
    await expect(page.locator('[aria-label="Spreadsheet"]')).toHaveCount(1);
    expect(await button.getAttribute('aria-label')).toBe(label);
  });
});
